INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('eef4dab7-e0a1-434e-b09b-582253033cc6', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$91. óra: Feladatmegoldás$q$, $q$Hétköznapi vásárlási, méréseket és egyenleteket tartalmazó szöveges feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "25dcbddf-ac7a-41aa-8c5c-8a36ad876a3f", "text": "3 füzet és 1 toll összesen 1100 Ft-ba kerül. A toll ára 200 Ft. Hány Ft 1 füzet ára? (3x + 200 = 1100 -> 3x = 900)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "0f04c892-60cf-4594-90b7-93a289857c90", "text": "Peti 2000 Ft-tal ment a boltba. Vett 3 kg narancsot 500 Ft/kg áron. Hány Ft visszajárót kapott? (2000 - 1500)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "1df4ca4e-bf01-40ce-9fdf-d70c678c5127", "text": "Egy raktárban 120 láda gyümölcs van. Az első nap elvitték a 1/3-át, a második nap a megmaradt ládák felét. Hány láda maradt? (120 - 40 = 80, 80 - 40)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "25659f79-75fe-49c8-8887-9f6769e3a4c6", "text": "A mindennapi életben sok probléma modellezhető egyenlettel.", "type": "true-false", "options": [{"id": "55f06e36-c9c1-49d1-bbf6-fd8fea4183db", "text": "Igaz", "isCorrect": true}, {"id": "6f4bc637-7fbb-4664-8119-27bc0ab371ba", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "35b48cd1-ec01-4b25-807a-4001c8145cce", "text": "Melyik egyenlet írja le: 'Egy szám 4-szeresénél 5-tel több a 25'? (4x + 5 = 25)", "type": "multiple-choice", "options": [{"id": "150e7d6a-6c2d-42c4-be2b-c81ad377ed92", "text": "4x + 5 = 25", "isCorrect": true}, {"id": "fccc10ff-c802-4272-8fae-19e3bb659b2b", "text": "x + 4 + 5 = 25", "isCorrect": false}, {"id": "dd7ec91e-bb2a-4178-a0be-d1cb265c51e2", "text": "4x - 5 = 25", "isCorrect": false}, {"id": "43097444-caf3-4d19-803e-b50e74b3d179", "text": "x / 4 + 5 = 25", "isCorrect": false}], "timeLimit": 15}, {"id": "a2eb5728-bef0-4b01-99a7-447f490c01f7", "text": "Mennyi a gondolt szám a 4x + 5 = 25 egyenletben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "65ae73b8-3711-4da2-8897-f8e754f412c4", "text": "Az ellenőrzést a feladat eredeti szövegébe való behelyettesítéssel végezzük.", "type": "true-false", "options": [{"id": "f861bfb3-dafa-460c-a3ea-8336ebbb01ac", "text": "Igaz", "isCorrect": true}, {"id": "c7adf76c-9798-4fd6-aef2-b450828d2e7e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cd16b7c9-7ba4-4dff-a915-2eeb2387a040', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$92. óra: Több megoldás is lehet$q$, $q$Több megoldást megengedő szöveges feladatok és egyenlőtlenségek vizsgálata.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "4b79daef-11e1-40fb-b7a8-69245d2af4e4", "text": "Katinak legfeljebb 10 Ft-ja lehet, és páros számú forintja van. Hányféle lehetséges összege lehet természetes számokban? (0, 2, 4, 6, 8, 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "13436ba2-3e99-4946-9db1-7701277b4ae9", "text": "Mely kifejezés jelenti azt, hogy 'legfeljebb 5'?", "type": "multiple-choice", "options": [{"id": "8547f957-ec4e-4d42-b9cb-8695177ac8aa", "text": "Kisebb vagy egyenlő, mint 5 (x <= 5)", "isCorrect": true}, {"id": "e47723d1-2043-4003-8a8d-a7b50b3e8104", "text": "Nagyobb, mint 5", "isCorrect": false}, {"id": "9504f970-6bae-4317-974b-665ef7270dc4", "text": "Pontosan 5", "isCorrect": false}, {"id": "f443d2a8-e73d-40ed-bc95-15a077dbc077", "text": "Legalább 5", "isCorrect": false}], "timeLimit": 15}, {"id": "f2de64b3-47cb-4335-aeb7-5bd213bcbfbd", "text": "Mely kifejezés jelenti azt, hogy 'legalább 5'?", "type": "multiple-choice", "options": [{"id": "5603c662-5c66-4ca6-918f-a1b33d8c8fd2", "text": "Nagyobb vagy egyenlő, mint 5 (x >= 5)", "isCorrect": true}, {"id": "c995aa75-1144-4385-a6c2-47df1fd6be57", "text": "Kisebb, mint 5", "isCorrect": false}, {"id": "894c0d6d-7452-46cb-852e-3f363a43e6c5", "text": "Pontosan 5", "isCorrect": false}, {"id": "729b7e7f-8efa-43d2-a7e0-b4b9c9c63477", "text": "Legfeljebb 5", "isCorrect": false}], "timeLimit": 15}, {"id": "b072342a-70d6-4d7a-acc4-78c9bcbfba0e", "text": "A 'legalább 3 és legfeljebb 6' feltételnek eleget tevő egész számok száma: 3, 4, 5, 6 (összesen 4 szám).", "type": "true-false", "options": [{"id": "c9c08756-faaa-4ead-b67b-9fe2b6081507", "text": "Igaz", "isCorrect": true}, {"id": "276a7937-a2af-4a7b-98ce-2e136fe560e0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "744aef9d-4ad7-4080-a898-7d5f446d1e89", "text": "Hány természetes szám megoldása van a 2 * x <= 8 egyenlőtlenségnek? (x = 0, 1, 2, 3, 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "0e2cdece-56af-430c-a504-b88a6144aa99", "text": "A több megoldással rendelkező feladatoknál az összes megoldás megtalálása a cél.", "type": "true-false", "options": [{"id": "b499ba23-d13b-4d7a-bf6f-fd56b01b19ca", "text": "Igaz", "isCorrect": true}, {"id": "8b7d3a4c-cd40-4fcf-8f3b-5408d37282bc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d3517374-d16a-4f94-b510-86a5f55e0938", "text": "Melyik legkisebb természetes szám teljesíti az x > 7 egyenlőtlenséget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('6252ccbc-d980-4d5c-b52c-866e690fec41', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$93. óra: Létraverseny II.$q$, $q$Versenyszerű feladatmegoldás páros munkában a százalék és szöveges feladatok témakörében.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "51e874cf-a2f1-42b7-b1c8-160c23fec14d", "text": "Mennyi 1000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "4e173f9f-e61f-48a4-a12d-653167b8a3bd", "text": "Melyik szám teszi igazzá: 2 * x + 10 = 50?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "6f416157-f54c-4886-9f77-2578197f3b8f", "text": "Ha 3 kg narancs 1200 Ft, mennyibe kerül 5 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "507c31b2-6488-4ebc-addc-469d15cd62cb", "text": "Hány százalék felel meg a 3/5 törtnek? (3/5 = 60/100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "e1259634-da75-4bb2-9e47-0221ebc34f1b", "text": "Gondoltam egy számot, elosztottam 3-mal, hozzáadtam 4-et és 10-et kaptam. Mi a szám? ((10-4)*3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "26823eb8-f31c-45c3-bd93-7fc74cb12ca2", "text": "A játékos feladványok erősítik az osztály közösségét és a matematikai önbizalmat.", "type": "true-false", "options": [{"id": "8bd495f4-f114-4618-8ca9-c13b0b18a0e3", "text": "Igaz", "isCorrect": true}, {"id": "b24b0671-2b07-4374-8283-982b338dbc0d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c8f8a8a8-4227-403d-9e8d-d329bc78657a", "text": "Mennyi 400-nak a 25%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('37fb370e-dcb5-4631-a56d-98c178cd4c4d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$94. óra: Összefoglalás$q$, $q$A fejezet fogalmainak (arány, egyenes arányosság, százalék, nyitott mondatok) összefoglalása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "72c80d73-88d4-4ce0-9289-1dd70ac59839", "text": "Mennyi a 8 : 24 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "7e58893b-287c-4943-85f6-e0bf0705dc32", "text": "1 : 3", "isCorrect": true}, {"id": "9fe6bedf-0d86-47f4-a0fc-dad8b9c18df7", "text": "1 : 4", "isCorrect": false}, {"id": "91dac73f-dda1-4457-95aa-e6154975ab74", "text": "2 : 3", "isCorrect": false}, {"id": "32f5876f-234a-4581-94aa-1259885519fa", "text": "3 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "dae60117-4f7f-478e-850c-39d62ef67e2f", "text": "Hány százalék felel meg a 1/2-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "96559cee-ed07-4205-a6a6-4617ce59771c", "text": "Hány százalék felel meg a 1/5-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "9fcf9ce7-fa46-4f40-9e68-c2d085d5af82", "text": "Mennyi 600 Ft-nak a 30%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "d6a6011b-9d19-49eb-82d2-afc3216e9341", "text": "Melyik szám teszi igazzá: 4 * x - 8 = 32? (40/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e1f35ff3-70c9-4200-b316-a719bc4edd99", "text": "Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "7186f9f7-5371-4531-9b85-946f9113328c", "text": "Igaz", "isCorrect": true}, {"id": "4ad1aa1c-392a-492b-b72a-437b7d7931fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "52e906bb-57ef-4b9f-ad5a-689e1882850e", "text": "Mennyi 150-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c46f6252-44bf-4c32-9f55-582335a2b86e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$95. óra: Gyakorlóóra$q$, $q$Gyakorló feladatok önállóan, becslés és ellenőrzés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "dd73aad3-9fbe-4776-a89a-029a9e27250c", "text": "Egy 8000 Ft-os táska ára 25%-kal csökkent. Hány Ft a kedvezmény? (8000 * 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "b7937cf8-20b1-49c3-8138-ceeaa7fd3fc2", "text": "Mennyi a táska új ára? (8000 - 2000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6000"}, {"id": "34b4aee3-85f6-4fe2-bcb5-6f06510b46a7", "text": "Melyik szám teszi igazzá: (x + 4) : 5 = 6?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "26"}, {"id": "6b16303a-91a6-4b20-8289-cff6045f3b86", "text": "Ha 4 kg alma 1600 Ft, egyenes arányosság esetén 7 kg alma 2800 Ft-ba kerül.", "type": "true-false", "options": [{"id": "7285b393-cd17-49c9-bfe1-55fe53e35ffa", "text": "Igaz", "isCorrect": true}, {"id": "4da77160-9768-472a-a999-563f7bef38cc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bf4be081-77a3-4795-8422-49d7e6f78c1a", "text": "Mennyi 50-nek a 120%-a? (50 * 1,2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "6faf27ae-fb49-486f-9d61-03e449cd2cbe", "text": "Az ellenőrzés mindig megnyugtató visszajelzést ad a feladat helyességéről.", "type": "true-false", "options": [{"id": "6e92c097-c606-427d-803e-43621e10a4af", "text": "Igaz", "isCorrect": true}, {"id": "a4e8c4f0-4b19-4d13-9805-076c6aeec11c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4cf72ac0-c9bb-4f67-a331-bc8a6fdaa03a", "text": "Mennyi 1000-nek az 1%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('424edc17-0b18-4ff2-beed-d4245b37e584', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$96. óra: Témazáró dolgozat$q$, $q$Témazáró számonkérés az Arány, százalék, szöveges feladatok témakörből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "9d61567d-acfb-4e14-acbf-6bbf3022dd30", "text": "1. Mennyi a 10 : 35 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "d3a3fed4-e324-45a8-a0bf-262d3557c6b1", "text": "2 : 7", "isCorrect": true}, {"id": "415dd796-bcbc-487f-b374-42208b99e7c8", "text": "1 : 35", "isCorrect": false}, {"id": "b1601eed-71b6-40af-bfc4-8d38720942e5", "text": "2 : 5", "isCorrect": false}, {"id": "b4904124-616c-437e-8cb5-e1c27a7b636a", "text": "5 : 7", "isCorrect": false}], "timeLimit": 15}, {"id": "fe9e8d7b-f581-44b9-a3e2-ba457a46f574", "text": "2. Ossz el 600 Ft-ot 1 : 2 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "50aea665-088b-4ccc-8aa1-640a0dc16abc", "text": "3. Ha 3 kg narancs 1500 Ft, mennyibe kerül 4 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "ad0f131d-1205-440e-9b87-25ce60f8660f", "text": "4. Hány százalék felel meg a 3/4 törtszámnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "75"}, {"id": "5dfebcbc-ef63-40e7-bca4-2f183a850847", "text": "5. Mennyi 4000 Ft-nak a 15%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}, {"id": "306453de-91df-4f41-a7a7-8eb0a826bc7c", "text": "6. Melyik szám teszi igazzá: 3 * x + 8 = 35?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "9565379a-4b7f-458a-a046-e855ff516270", "text": "7. Gondoltam egy számot, elosztottam 2-vel, kivontam belőle 5-öt, 10-et kaptam. Mi a szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "d59b0f44-e01c-4ecf-b305-5568fb4acdf9", "text": "8. Mennyi 200-nak a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "dc0a3db5-4e75-4cb0-8fd1-12eab7789485", "text": "9. Az egyenes arányosság esetén a két mennyiség hányadosa állandó.", "type": "true-false", "options": [{"id": "9d140a9a-e11a-4d31-8198-9301281f9732", "text": "Igaz", "isCorrect": true}, {"id": "130cdfc0-5b70-4842-8274-286c8402411c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e8b922ab-1059-493a-91ec-ec4b478b0966", "text": "10. Egy 5000 Ft-os nadrág ára 10%-kal nőtt. Mennyi az új ár? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5500"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0173d2ba-8967-41a4-b0f7-9b446371fe9c', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$97. óra: Témazáró dolgozat értékelése$q$, $q$A témazáró dolgozat feladatainak megbeszélése, hibajavítás és összegzés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "be10d067-9d67-4609-9522-a9f7ed60eecd", "text": "Mi volt a legfontosabb tapasztalat a százalékszámítási feladatoknál?", "type": "multiple-choice", "options": [{"id": "bc1bf9c3-1633-45d8-bbfc-6e5759d07816", "text": "Az 1% kiszámítása vagy a törtalakkal való szorzás biztonságos számolást ad", "isCorrect": true}, {"id": "db6cff07-db78-4ebc-884e-8341fe8d1779", "text": "A százalékjel elhagyása", "isCorrect": false}, {"id": "30ec8e42-edc9-45d1-b911-a8356a0feb89", "text": "Mindig 100-at kell válaszolni", "isCorrect": false}, {"id": "43b61c40-247b-4a3d-91d1-25fc1c3ba768", "text": "Nem kell kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "54a103cd-4324-4fb4-a999-60823f1d5c7c", "text": "Az arányos osztásnál az arányszámok összege adja meg a részek számát.", "type": "true-false", "options": [{"id": "ddbbb793-c023-4359-a8fa-661b6a85506c", "text": "Igaz", "isCorrect": true}, {"id": "1311889a-dedd-48d5-9313-a5b86500b310", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "645d0768-166f-4b7a-a6c9-a1c0e6b72227", "text": "Mennyi 2000 Ft-nak a 20%-a?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "a9b80237-c505-4019-b4cc-20db12c4e809", "text": "Melyik szám teszi igazzá: 5 * x - 10 = 40?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "f8618406-8b29-404f-9319-ace4cc31e335", "text": "A hibák elemzése segít a sikeresbb jövőbeli teljesítményben.", "type": "true-false", "options": [{"id": "df4f1c63-849b-42dc-8a3b-d8ba5c65dc82", "text": "Igaz", "isCorrect": true}, {"id": "bc94b19c-7de6-46a4-8207-30ec7a0451eb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "890555d9-e0d9-430f-999b-e5344a4a56ee", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "f628aabb-d06a-4530-8a77-1d4e1c488330", "text": "Hány százalék felel meg az 1/10-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3ad809a9-dd12-4113-bb15-f9437e734e67', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$98. óra: Hosszúság, tömeg, idő$q$, $q$A hosszúság, tömeg és idő mérésének ismétlése, mértékegységek és átváltások.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "69fd4dd2-0fc2-4484-8256-8e73157e6b46", "text": "Hány milliméter 1 méter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "9787920f-c368-4b74-b2fa-d214d9b3d1ef", "text": "Hány dekagramm (dkg) 1 kilogramm (kg)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "37caf151-537c-402d-b9af-808af05b0308", "text": "Hány másodperc van 1 órában? (60 * 60)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3600"}, {"id": "ec3c81da-9144-45a9-885a-755913f6cebc", "text": "Mennyi 2,5 km méterben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "50cd4af2-3685-4284-ba9a-7e3e3421aa7f", "text": "Hány kilogramm 3,5 tonna?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}, {"id": "4620a857-0c86-4880-9336-5badcdd3ec13", "text": "Az időváltás 60-as alapon működik a másodperc, perc és óra között.", "type": "true-false", "options": [{"id": "786c782d-317c-444f-b43f-2c25d750b19d", "text": "Igaz", "isCorrect": true}, {"id": "ae4c7e8d-1468-43d9-b202-061c4affc6d5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15a15a03-12aa-475c-acb6-3d9684aed445", "text": "Hány perc 2 óra 15 perc?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "135"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('03a25900-cf30-4113-a311-fc448ec08b04', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$99. óra: Hosszúság, tömeg, idő II.$q$, $q$Összetett mértékegység-átváltási feladatok és gyakorlás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "47b6d52b-6c8e-40b4-bc40-8a22bdb1815d", "text": "Hány cm van 4,5 m-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "450"}, {"id": "de2dd715-3e98-46a1-a398-75aa16fc62ba", "text": "Hány gramm 0,75 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "750"}, {"id": "adc038d5-d5f3-4cfc-a301-23ed945cb0b0", "text": "Hány napból áll 4 hét?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "b9071945-f867-406c-bdee-84bc8226a562", "text": "A 1500 m megegyezik 1,5 km-rel.", "type": "true-false", "options": [{"id": "9a1664b2-35b4-41df-abe7-bef0696987db", "text": "Igaz", "isCorrect": true}, {"id": "ea9eec80-85e1-4f16-b360-b5ad29c7dcef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a4095ca2-a5a4-4bf2-887c-1a81895ae1e5", "text": "Mennyi 500 dkg kg-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "c576a073-ed2e-4acf-832e-2eddf203e7b7", "text": "Hány perc 1 nap negyede (6 óra)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "c9cf5f67-21f1-4170-8df3-2c43c99af879", "text": "A nagyobb mértékegységből kisebb felé haladva szorzunk a váltószámmal.", "type": "true-false", "options": [{"id": "4ee8f8fd-4b62-4b98-b3f9-0eae1b8e1d60", "text": "Igaz", "isCorrect": true}, {"id": "6c624aba-a8d2-42dd-aaa0-792bab600e61", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('a8c183a7-616f-46fb-9d8e-6c80ab32589a', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$100. óra: A sokszögek kerülete$q$, $q$Négyzet, téglalap, háromszög és sokszögek kerületének számítása (K).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "84147add-dd4d-47ea-8fad-3b24a9f6f487", "text": "Mi a téglalap kerületének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "808d4a7d-b999-4a3d-8864-6a9de0c04355", "text": "K = 2 * (a + b)", "isCorrect": true}, {"id": "00fde513-ea40-455f-b540-17b2d06d13ba", "text": "K = a * b", "isCorrect": false}, {"id": "dbe716e5-d223-446a-9ac3-c33bab0d3385", "text": "K = a + b", "isCorrect": false}, {"id": "0daf0367-09e8-477e-8992-ce8c3a856e68", "text": "K = 4 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "cfcdbc41-c19e-4f4e-9b72-f1a350264683", "text": "Mi a négyzet kerületének képlete ('a' oldallal)?", "type": "multiple-choice", "options": [{"id": "960d0a05-5770-4043-848b-69badb5a897d", "text": "K = 4 * a", "isCorrect": true}, {"id": "1cec317a-c8c9-429b-a6fb-c9037e74ba7e", "text": "K = a * a", "isCorrect": false}, {"id": "10c12e5b-8b61-4d9d-bafb-c50b8a01df37", "text": "K = 2 * a", "isCorrect": false}, {"id": "6922e192-e149-4cc3-ab43-7db9d74531de", "text": "K = 6 * a", "isCorrect": false}], "timeLimit": 15}, {"id": "9f072104-c797-4b7e-a784-700c580d6d39", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap kerülete? (2 * (6 + 8))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "0e50c001-78a5-41c1-a94b-1b0bb8818577", "text": "Mennyi a 7 cm oldalú négyzet kerülete? (4 * 7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "540de2f1-0e9b-4721-84dd-80827efa0326", "text": "Mennyi a 3 cm, 4 cm, 5 cm oldalú háromszög kerülete? (3+4+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "a618b575-9c43-4058-ad91-0711aee56c2d", "text": "A kerület a sokszöget határoló oldalak hosszának összege.", "type": "true-false", "options": [{"id": "52c9de36-8bb4-4dfd-8236-fe5a790d9f08", "text": "Igaz", "isCorrect": true}, {"id": "cfcfb044-f44d-496d-9da9-28090b4388f6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dc81a4c7-7d83-47ee-9c5d-6229a5d7856c", "text": "Mennyi a 5 cm oldalú szabályos ötszög kerülete? (5 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;